   241  static FT_Int32 getFTLoadFlags(GBool type1, GBool trueType, GBool aa, GBool enableFreeTypeHinting, GBool enableSlightHinting)
   242  {
   243    int ret = FT_LOAD_DEFAULT;
   244    if (aa)
   245      ret |= FT_LOAD_NO_BITMAP;
   246
   247    if (enableFreeTypeHinting) {
   248      if (enableSlightHinting) {
   249        ret |= FT_LOAD_TARGET_LIGHT;
   250      } else {
   251        if (trueType) {
   252          // FT2's autohinting doesn't always work very well (especially with
   253          // font subsets), so turn it off if anti-aliasing is enabled; if
   254          // anti-aliasing is disabled, this seems to be a tossup - some fonts
   255          // look better with hinting, some without, so leave hinting on
   256          if (aa) {
   257            ret |= FT_LOAD_NO_AUTOHINT;
   258          }
   259        } else if (type1) {
   260          // Type 1 fonts seem to look better with 'light' hinting mode
   261          ret |= FT_LOAD_TARGET_LIGHT;
   262        }
   263      }
   264    } else {
   265      ret |= FT_LOAD_NO_HINTING;
   266    }
   267    return ret;
   268  }
